LOG = []


def patch(rel, data):
    if rel not in FILES:
        return data
    d = bytearray(data); n = 0
    for o, old, new in FILES[rel]:
        if d[o] == new: continue
        assert d[o] == old, (rel, hex(o), d[o], old)
        d[o] = new; n += 1
    LOG.append('oxswap %s: %d bytes' % (rel, n))
    return bytes(d)
